190	    @Override
191	    public Map<Long, Long> tradeCountByColorIds(List<Long> colorIds) {
192	        if (colorIds == null || colorIds.isEmpty()) {
193	            return Collections.emptyMap();
194	        }
195	
196	        QOrderBid orderBid = QOrderBid.orderBid;
197	        QProductSize productSize = QProductSize.productSize;
198	
199	        List<Tuple> results = queryFactory.select(
200	                        productSize.productColor.id,
201	                        orderBid.id.count()
202	                )
203	                .from(orderBid)
