205	                .where(
206	                        productSize.productColor.id.in(colorIds),
207	                        orderBid.status.eq(BidStatus.COMPLETED)
208	                )
209	                .groupBy(productSize.productColor.id)
210	                .fetch();
211	
212	        return results.stream()
213	                .collect(Collectors.toMap(
214	                        t -> t.get(productSize.productColor.id),
215	                        t -> t.get(orderBid.id.count())
216	                ));
217	    }
